const CONFIG = {
  geography: {
    topicSeed: "geography — why places are the way they are: borders, terrain, climate, cities, trade, why-is-X-shaped-like-that. Recognizable countries/landmarks preferred.",
    visualStyle: "vivid explanatory geography documentary, aerial and satellite feel, rich natural color",
    captionStyle: "neutral", voiceId: "UgBBYS2sOqTuMpoF3BR0", tone: "curious, clear, explanatory", accent: "#2E86DE",
  },
  historical_mysteries: {
    topicSeed: "historical mysteries — unexplained disappearances, lost places, unsolved events, famous figures with a hidden gap in the record. Recognizable names/events preferred.",
    visualStyle: "mysterious historical documentary, dramatic low-key lighting, aged and cinematic",
    captionStyle: "serious", voiceId: "UgBBYS2sOqTuMpoF3BR0", tone: "ominous, intriguing, story-driven", accent: "#E67E22",
  },
};
const niche = $json.niche || 'geography';
const cfg = CONFIG[niche];
if (!cfg) throw new Error(`Unknown niche "${niche}" — must be one of ${Object.keys(CONFIG).join(', ')}`);
return { json: { niche, ...cfg } };

const cfg = $('Resolve Niche Config').item.json;
const raw = $input.first().json;
const topics = Array.isArray(raw.topics) ? raw.topics : [];
return { json: { ...cfg, topics, scriptAttempt: 0, lastErrors: [] } };

const r = $input.first().json;
if (r.error) throw new Error('Claude API error: ' + JSON.stringify(r.error));
const textBlock = (r.content||[]).find(b => b.type === 'text');
let raw = (textBlock && textBlock.text) ? textBlock.text.trim() : '';
if (!raw) throw new Error('Blueprint returned no text');
if (r.stop_reason === 'max_tokens') throw new Error('Blueprint truncated (max_tokens) - raise max_tokens');
if (raw.startsWith('```')) raw = raw.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
function extract(s){const a=s.indexOf('{');if(a<0)return null;let d=0,q=false,e=false;for(let i=a;i<s.length;i++){const c=s.charCodeAt(i);if(q){if(e)e=false;else if(c===92)e=true;else if(c===34)q=false;}else if(c===34)q=true;else if(c===123)d++;else if(c===125){d--;if(d===0)return s.slice(a,i+1);}}return null;}
function tp(s){try{const v=JSON.parse(s);return (v&&typeof v==='object')?v:undefined;}catch(e){return undefined;}}
const bp = tp(raw) || tp(extract(raw));
if (!bp || !Array.isArray(bp.acts) || !bp.acts.length) throw new Error('Blueprint JSON invalid: ' + raw.slice(0,300));
const usage = r.usage || {};
return { json: { ...$('Prep').item.json, blueprint: bp, acts: bp.acts, priorSummaries: [], scenes: [], nextIndex: 0, claudeIn: (usage.input_tokens||0), claudeOut: (usage.output_tokens||0) } };

const r = $input.first().json;
if (r.error) throw new Error('Claude API error: ' + JSON.stringify(r.error));
const tb = (r.content||[]).find(b=>b.type==='text');
let raw = (tb && tb.text) ? tb.text.trim() : '';
if (r.stop_reason === 'max_tokens') throw new Error('Act truncated (max_tokens)');
if (raw.startsWith('```')) raw = raw.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
function extract(s){const a=s.indexOf('{');if(a<0)return null;let d=0,q=false,e=false;for(let i=a;i<s.length;i++){const c=s.charCodeAt(i);if(q){if(e)e=false;else if(c===92)e=true;else if(c===34)q=false;}else if(c===34)q=true;else if(c===123)d++;else if(c===125){d--;if(d===0)return s.slice(a,i+1);}}return null;}
function tp(s){try{const v=JSON.parse(s);return (v&&typeof v==='object')?v:undefined;}catch(e){return undefined;}}
const act = tp(raw) || tp(extract(raw));
if (!act || !Array.isArray(act.scenes)) throw new Error('Act JSON invalid: ' + raw.slice(0,300));
const u = r.usage || {};
act._in = (u.input_tokens||0); act._out = (u.output_tokens||0);
return { json: act };

const st = $('Parse Blueprint').item.json;
const acc = $('Accumulate').all().map(i=>i.json).sort((a,b)=>a.act_index-b.act_index);
let scenes = [];
for (const a of acc) for (const s of (a.scenes||[])) scenes.push(s);
scenes.sort((a,b)=>a.scene_index-b.scene_index);
// append spoken outro scene (narrated share CTA over a kinetic_text card)
const maxIdx = scenes.reduce((m,s)=>Math.max(m, Number(s.scene_index)||0), -1);
const outroLine = (st.blueprint.outro_line || 'If this got you, send it to someone who needs to see it.').trim();
scenes.push({ scene_index: maxIdx+1, point: 'outro', narration: outroLine, visual_source: 'template', template_name: 'kinetic_text', template_data: { line: 'Like, Share, Follow', is_outro: true } });
const claudeIn = st.claudeIn + acc.reduce((s,a)=>s+(a._in||0),0);
const claudeOut = st.claudeOut + acc.reduce((s,a)=>s+(a._out||0),0);
return { json: { ...st, blueprint: st.blueprint, scenes, claudeIn, claudeOut } };

const st = $input.first().json;
const bp = st.blueprint || {};
const scenes = st.scenes || [];
const errors = [];
const content = scenes.filter(s => !(s.template_data && s.template_data.is_outro));
if (content.length < 20) errors.push({stage:'structure', msg:`only ${content.length} content scenes (need >=20)`});
if (content.length > 70) errors.push({stage:'structure', msg:`too many scenes (${content.length})`});
let words = 0;
const noText = /(readable|legible|\btext\b|document|receipt|screen|\bUI\b|currency|banknote|logo|\bsign\b|caption|number)/i;
content.forEach((s,i) => {
  if (!s.narration || s.narration.trim().length < 5) errors.push({stage:'structure', msg:`scene ${i} narration too short`});
  words += (s.narration||'').trim().split(/\s+/).filter(Boolean).length;
  const terms = [].concat(s.search_terms||[], s.fallback_terms||[]);
  if (!Array.isArray(s.search_terms) || s.search_terms.length < 3 || s.search_terms.length > 6) errors.push({stage:'structure', msg:`scene ${i} search_terms must be 3-6`});
  if (!Array.isArray(s.fallback_terms) || s.fallback_terms.length < 2 || s.fallback_terms.length > 4) errors.push({stage:'structure', msg:`scene ${i} fallback_terms must be 2-4`});
  if (!s.visual_style) errors.push({stage:'structure', msg:`scene ${i} missing visual_style`});
  for (const t of terms) if (noText.test(String(t))) { errors.push({stage:'structure', msg:`scene ${i} visual term "${t}" would need readable text/UI - rewrite`}); break; }
});
if (words > 2000) errors.push({stage:'structure', msg:`narration ${words} words exceeds 2000 hard cap`});
if (words < 1000) errors.push({stage:'structure', msg:`narration ${words} words below 1000`});
const medical = /\b(disease|illness|symptom|diagnos|treatment|medication|surgery|surgical|cancer|tumor|infection|syndrome|disorder|therapy|prescription|patient|clinical|vaccine|antibiotic)\b/i;
const scan = [bp.hook, bp.title, ...content.map(s=>s.narration||'')].join(' ');
if (medical.test(scan)) errors.push({stage:'topic', msg:'medical/health content detected - retry with different topic'});
if (errors.length) return { json: { ...st, _scriptValid: false, _validationErrors: errors } };
return { json: { ...st, hook: bp.hook, title: bp.title, comment_hook: bp.comment_hook, outro_line: bp.outro_line, thumbnail_text: bp.thumbnail_text, thumbnail_concept: bp.thumbnail_concept, seo_description: bp.seo_description, tags: bp.tags, caption_style: bp.caption_style, script_word_count: words, num_scenes: content.length, _scriptValid: true } };

const st = $('Parse Blueprint').item.json;
const prev = st.scriptAttempt || 0;
const errors = ($input.first().json._validationErrors)||[];
console.log(`Script validation failed on attempt ${prev+1}:`, JSON.stringify(errors));
return { json: { ...$('Prep').item.json, scriptAttempt: prev+1, lastErrors: errors } };

const item = $input.item.json;
const si = $('Split Out Scenes').item.json.scene_index;
if (!item.audio_base64) throw new Error(`TTS missing audio_base64 for scene ${si}`);
if (!item.alignment) throw new Error(`TTS missing alignment for scene ${si}`);
return { json: { scene_index: si, chars: ($('Split Out Scenes').item.json.narration||'').length, audio: item } };

const scene = $('Loop Over Scenes').item.json;
const si = scene.scene_index;
let item = $input.item.json;
let url = item && item.images && item.images[0] && item.images[0].url;
let degraded = false;
// Templates (outro) pass through as template scenes
if (scene.visual_source === 'template') {
  return { json: { scene_index: si, visual_source: 'template', template_name: scene.template_name, template_data: scene.template_data } };
}
if (!url) {
  // Primary Fal failed (node set to continue on error). Signal a gradient placeholder;
  // long-compose substitutes a house-style background for scenes flagged _degraded.
  degraded = true;
}
return { json: { scene_index: si, images: url ? [url] : [], _degraded: degraded } };

const all = $input.all().map(i=>i.json);
const visAgg = all.find(i => Array.isArray(i.data) && i.data[0] && (i.data[0].images || i.data[0].visual_source==='template'));
const audAgg = all.find(i => Array.isArray(i.data) && i.data[0] && i.data[0].audio);
if (!visAgg) throw new Error('visual branch missing');
if (!audAgg) throw new Error('audio branch missing');
const v = $('Validate Final Script').first().json;
const degraded = visAgg.data.filter(x=>x._degraded).length;
const merged = visAgg.data.map(vi => {
  const a = audAgg.data.find(x=>x.scene_index===vi.scene_index);
  if (!a) throw new Error('no audio for scene ' + vi.scene_index);
  return { scene_index: vi.scene_index, images: vi.images, visual_source: vi.visual_source, template_name: vi.template_name, template_data: vi.template_data, _degraded: vi._degraded, audio: a.audio };
}).sort((x,y)=>x.scene_index-y.scene_index);
const chars = audAgg.data.reduce((s,x)=>s+(x.chars||0),0);
return { json: { hook: v.hook, comment_hook: v.comment_hook, caption_style: v.caption_style, thumbnail_text: v.thumbnail_text, degraded_scenes: degraded, elevenlabs_chars: chars, num_scenes: v.num_scenes, script_word_count: v.script_word_count, claudeIn: v.claudeIn, claudeOut: v.claudeOut, niche: v.niche, topic: v.blueprint.topic, thumbnail_concept: v.thumbnail_concept, accent: v.accent, data: merged } };

const j = $input.first().json;
if (j.success !== true) throw new Error('Compose failed: ' + (j.error||'unknown') + ' job ' + (j.job_id||''));
if (!j.output_path) throw new Error('Compose missing output_path');
return { json: j };
